#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    long long minCostToConvertString(std::string source, std::string target, 
                                   std::vector<char>& original, std::vector<char>& changed, std::vector<int>& cost) {
        long long INF = 1e15;
        std::vector<std::vector<long long>> dist(26, std::vector<long long>(26, INF));
        for (int i = 0; i < 26; ++i) dist[i][i] = 0;
        for (size_t i = 0; i < original.size(); ++i) {
            int u = original[i] - 'a';
            int v = changed[i] - 'a';
            dist[u][v] = std::min(dist[u][v], (long long)cost[i]);
        }
        for (int k = 0; k < 26; ++k) {
            for (int i = 0; i < 26; ++i) {
                for (int j = 0; j < 26; ++j) {
                    if (dist[i][k] + dist[k][j] < dist[i][j]) {
                        dist[i][j] = dist[i][k] + dist[k][j];
                    }
                }
            }
        }
        long long total = 0;
        for (size_t i = 0; i < source.size(); ++i) {
            int u = source[i] - 'a';
            int v = target[i] - 'a';
            if (dist[u][v] >= INF) return -1;
            total += dist[u][v];
        }
        return total;
    }
};

import java.util.*;

class Solution {
    public long minCostToConvertString(String source, String target, char[] original, char[] changed, int[] cost) {
        long INF = (long)1e15;
        long[][] dist = new long[26][26];
        for (long[] row : dist) Arrays.fill(row, INF);
        for (int i = 0; i < 26; i++) dist[i][i] = 0;
        for (int i = 0; i < original.length; i++) {
            int u = original[i] - 'a';
            int v = changed[i] - 'a';
            dist[u][v] = Math.min(dist[u][v], cost[i]);
        }
        for (int k = 0; k < 26; k++) {
            for (int i = 0; i < 26; i++) {
                for (int j = 0; j < 26; j++) {
                    if (dist[i][k] + dist[k][j] < dist[i][j]) {
                        dist[i][j] = dist[i][k] + dist[k][j];
                    }
                }
            }
        }
        long total = 0;
        for (int i = 0; i < source.length(); i++) {
            int u = source.charAt(i) - 'a';
            int v = target.charAt(i) - 'a';
            if (dist[u][v] >= INF) return -1;
            total += dist[u][v];
        }
        return total;
    }
}

